SELECT workspace_member_id
FROM workspace_members
WHERE workspace_id = #{workId}
	AND member_id = #{memberId}
	AND status = 0

	SELECT COUNT(*)
    FROM workspace_domains
    WHERE domain_key = #{domainKey}
      AND workspace_id = #{workId}
      AND active = 'Y'

mapper.update:

UPDATE chat_room_members SET last_read_message_id = #{messageId}
WHERE chat_room_member_id = #{chatRoomMemberId}
  AND chat_room_id = #{chatRoomId}
  AND status = 0
  AND #{messageId} > NVL(visible_after_message_id, 0)
  AND (last_read_message_id IS NULL
       OR last_read_message_id < #{messageId})
  AND EXISTS (
      SELECT 1
      FROM chat_messages
      WHERE chat_room_id = #{chatRoomId}
        AND message_id = #{messageId}
        AND deleted IS NULL
  )

mapper.select:
SELECT NVL(MAX(message_id), 0)
FROM chat_messages
WHERE chat_room_id = #{chatRoomId}
